/*
	VIOC_heli_attack.sqf - agregado por tools/vio_build.py (parche heli_attack; no es del autor de la mision).
	Fuente: work/v6_build/heli_attack/.

	Servidor de HELICOPTEROS, el tercer tipo del panel "PEDIR: Apoyo aereo" (tipo "heli"; el pedido lo valida y lo cobra
	VIOC_AS_fnc_requestDo en VIOC_air_support_server.sqf y luego llama a VIOC_HA_fnc_launch):
	  - VIOC_ASS_HA_N (3) helicopteros de ataque del bando (VIOC_ASS_CLASS select 2: AH-64D Apache; Rusia Mi-28N, Ka-52 o
	    Mi-24) aparecen a VIOC_HA_SPAWN m del blanco, del lado de lo propio, y vuelan juntos hacia el punto marcado sin
	    distraerse (CARELESS).
	  - Cuando el primero llega (a menos de VIOC_HA_NEAR m), todos pasan a combate (COMBAT / RED) con una orden de
	    buscar y destruir (SAD) alrededor del blanco, a VIOC_HA_FLY m de altura, durante VIOC_ASS_HA_LIFE s (lobby
	    VIOC_HELI_DURATION, 5 min). Cada 5 s se les revelan los enemigos a menos de VIOC_ASS_HA_ZONE m (300) del blanco
	    (infanteria primero; no los que estan a menos de 30 m de tropas propias) y el artillero apunta al grupo de
	    infanteria mas denso (3 o mas hombres en 25 m). El que se aleja mas de VIOC_HA_NEAR + 300 m vuelve.
	  - El que queda muy danado (> 0,6) o sin municion se va antes. Al terminar se van todos a base y se borran cuando no
	    hay jugadores cerca (VIOC_AS_fnc_planeGone). Se les puede derribar.
	  - Espera del bando: VIOC_ASS_HA_CD (lobby VIOC_HELI_COOLDOWN); si caen TODOS, VIOC_ASS_HA_CD_LOST (lobby
	    VIOC_HELI_LOST_COOLDOWN). Si ninguno llega en VIOC_HA_ARRIVE_T s, se cancela y se devuelve el dinero.
	  - Bajas: cuenta los enemigos a pie que matan (EntityKilled) y las dice al final.
	Solo servidor (lo carga VIOC_air_support_server.sqf).
	Consola (servidor; en partida alojada vale "Ejecucion local"):
	    ["heli", screenToWorld [0.5,0.5]] call VIOC_AS_fnc_force;   helicopteros gratis donde miras
	    [west] call VIOC_HA_fnc_end;                                  los helicopteros de ese bando se van ya
	    hint (call VIOC_AS_fnc_status);                              estado del apoyo aereo (con los helicopteros)
*/
if (!isServer) exitWith {};
if (!isNil "VIOC_HA_STARTED") exitWith {};
VIOC_HA_STARTED = true;

VIOC_HA_SPAWN = 3500;		//--- m del blanco donde aparecen
VIOC_HA_ALT = 150;			//--- m de altura al llegar y al irse
VIOC_HA_FLY = 70;			//--- m de altura durante el ataque
VIOC_HA_NEAR = 900;			//--- m: "llego" (y correa: a mas de esto + 300 m vuelve)
VIOC_HA_ARRIVE_T = 240;		//--- s maximos para que llegue el primero (si no, se cancela y se devuelve el dinero)
VIOC_HA_SAFE = 30;			//--- m: no se les revelan enemigos tan cerca de tropas propias
VIOC_HA_KILLS = createHashMap;	//--- id del pedido -> enemigos a pie muertos por sus helicopteros

//--- Bajas: el que mato (o el que disparo) va en un helicoptero de un pedido y el muerto era enemigo de ese bando.
addMissionEventHandler ["EntityKilled", {
	params ["_u", "_k", "_i"];
	if (!(_u isKindOf "CAManBase")) exitWith {};
	private _src = if (isNull _i) then {_k} else {_i};
	if (isNull _src) exitWith {};
	private _id = (vehicle _src) getVariable ["vioc_ha_id", -1];
	if (_id < 0) exitWith {};
	private _hs = (vehicle _src) getVariable ["vioc_ha_side", sideUnknown];
	private _us = side group _u;
	if (!(_us in [west, east, resistance]) || {(_hs getFriend _us) >= 0.6}) exitWith {};
	VIOC_HA_KILLS set [_id, (VIOC_HA_KILLS getOrDefault [_id, 0]) + 1];
}];

//--- true si al helicoptero le queda municion de verdad (no cuentan bengalas ni el designador laser).
VIOC_HA_fnc_hasAmmo = {
	params ["_h"];
	((magazinesAllTurrets _h) findIf {
		((_x select 2) > 0) && {!((getText (configFile >> "CfgAmmo" >> (getText (configFile >> "CfgMagazines" >> (_x select 0) >> "ammo")) >> "simulation")) in ["shotCM", "laserDesignate"])}
	}) >= 0
};

//--- Fuera de combate: destruido, inmovil o sin piloto vivo.
VIOC_HA_fnc_down = {
	params ["_h"];
	isNull _h || {!alive _h} || {!canMove _h} || {isNull (driver _h)} || {!alive (driver _h)}
};

//--- Enemigos alrededor del blanco: [hombres a pie (por distancia), vehiculos con tripulacion].
VIOC_HA_fnc_targets = {
	params ["_pos", "_side"];
	private _men = [];
	private _veh = [];
	{
		if (alive _x) then {
			if (_x isKindOf "CAManBase") then {
				private _s = side group _x;
				if ((_s in [west, east, resistance]) && {(_side getFriend _s) < 0.6}) then {_men pushBack _x};
			} else {
				if (({alive _x} count (crew _x)) > 0) then {
					private _s = side _x;
					if ((_s in [west, east, resistance]) && {(_side getFriend _s) < 0.6}) then {_veh pushBack _x};
				};
			};
		};
	} forEach (_pos nearEntities [["CAManBase", "LandVehicle", "StaticWeapon"], VIOC_ASS_HA_ZONE]);
	_men = [_men, [_pos], {_x distance2D _input0}, "ASCEND"] call BIS_fnc_sortBy;
	if (count _men > 24) then {_men resize 24};
	_men = _men select {!([getPosATL _x, _side, VIOC_HA_SAFE] call VIOC_AS_fnc_friendlyNear)};
	_veh = _veh select {!([getPosATL _x, _side, VIOC_HA_SAFE] call VIOC_AS_fnc_friendlyNear)};
	[_men, _veh]
};

//--- Orden de buscar y destruir alrededor del blanco.
VIOC_HA_fnc_sad = {
	params ["_g", "_pos", "_k"];
	private _p = _pos getPos [80 + random 70, _k * 120 + random 60];
	private _wp = _g addWaypoint [_p, 0];
	_wp setWaypointType "SAD";
	_wp setWaypointBehaviour "COMBAT";
	_wp setWaypointCombatMode "RED";
	_wp setWaypointSpeed "NORMAL";
	_g setCurrentWaypoint _wp;
};

//--- Un helicoptero se va a base y se borra cuando nadie lo ve (planeGone; si cae en el camino, restos al recolector).
VIOC_HA_fnc_home = {
	params ["_h", "_g", "_pos", "_side"];
	if (isNull _h || {!alive _h}) exitWith {};
	private _home = [_side, _pos] call VIOC_AS_fnc_home;
	private _hd = if ((count _home > 1) && {(_home distance2D _pos) > 50}) then {_pos getDir _home} else {_pos getDir _h};
	private _away = _pos getPos [7000, _hd];
	_g setBehaviour "CARELESS";
	_g setCombatMode "BLUE";
	_h flyInHeight VIOC_HA_ALT;
	private _wp = _g addWaypoint [_away, 0];
	_wp setWaypointType "MOVE";
	_wp setWaypointBehaviour "CARELESS";
	_wp setWaypointCombatMode "BLUE";
	_wp setWaypointSpeed "FULL";
	_g setCurrentWaypoint _wp;
	[_h, _g, _away, VIOC_ASS_GONE_T] spawn VIOC_AS_fnc_planeGone;
};

//--- Crea los helicopteros del pedido _e (ya cobrado y en VIOC_ASS_ACTIVE). Devuelve "ok" o el motivo (y devuelve el dinero).
VIOC_HA_fnc_launch = {
	params ["_e", "_player", "_pos"];
	private _side = _e get "side";
	private _cls = _e get "cls";
	private _price = _e get "price";
	private _id = _e get "id";
	private _home = [_side, _pos] call VIOC_AS_fnc_home;
	private _dir = if ((count _home > 1) && {(_home distance2D _pos) > 50}) then {_pos getDir _home} else {random 360};
	private _sp = _pos getPos [VIOC_HA_SPAWN, _dir];
	_sp = [((_sp select 0) max 300) min (worldSize - 300), ((_sp select 1) max 300) min (worldSize - 300), 0];
	private _hd = _sp getDir _pos;
	private _helis = [];
	private _grps = [];
	private _err = "";
	for "_i" from 0 to (VIOC_ASS_HA_N - 1) do {
		private _p = _sp getPos [(_i - ((VIOC_ASS_HA_N - 1) / 2)) * 90, _hd + 90];
		private _r = [_side, _cls, [_p select 0, _p select 1, ((getTerrainHeightASL _p) max 0) + VIOC_HA_ALT], _hd, 40] call VIOC_AS_fnc_spawnPlane;
		if (_r isEqualType "") then {_err = _r} else {
			_r params ["_h", "_g"];
			_helis pushBack _h;
			_grps pushBack _g;
		};
	};
	if (count _helis == 0) exitWith {
		VIOC_ASS_ACTIVE = VIOC_ASS_ACTIVE select {(_x get "id") != _id};
		[_e, _price] call VIOC_AS_fnc_refund;
		format ["no se pudo crear ningun helicoptero: %1 (se te devolvieron los %2)", _err, _price]
	};
	//--- revision: si salieron menos, se devuelve la parte de los que faltan (y el precio del pedido baja)
	private _back = 0;
	if (count _helis < VIOC_ASS_HA_N && {_price > 0} && {!(_e getOrDefault ["free", false])}) then {
		_back = round (_price * (VIOC_ASS_HA_N - count _helis) / VIOC_ASS_HA_N);
		[_e, _back] call VIOC_AS_fnc_refund;
		_price = _price - _back;
		_e set ["price", _price];
	};
	{
		_x setVariable ["vioc_ha_id", _id];
		_x setVariable ["vioc_ha_side", _side];
		_x setVariable ["vioc_as_uid", _e get "uid", true];
		_x setVariable ["vioc_as_kind", "heli", true];
		_x flyInHeight VIOC_HA_ALT;
	} forEach _helis;
	{
		private _wp = _x addWaypoint [_pos, 0];
		_wp setWaypointType "MOVE";
		_wp setWaypointBehaviour "CARELESS";
		_wp setWaypointCombatMode "BLUE";
		_wp setWaypointSpeed "FULL";
		_x setCurrentWaypoint _wp;
	} forEach _grps;
	VIOC_HA_KILLS set [_id, 0];
	_e set ["plane", _helis select 0];
	_e set ["grp", _grps select 0];
	_e set ["helis", _helis];
	_e set ["grps", _grps];
	_e set ["center", _pos];
	_e set ["aim", _pos];
	_e set ["state", "fly"];
	private _dn = getText (configFile >> "CfgVehicles" >> _cls >> "displayName");
	private _who = name _player;
	[_player, true, format ["%1 helicopteros %2 en camino a la cuadricula %3: llegan en 1-2 min y atacan %4 min a los enemigos a menos de %5 m del punto (infanteria primero). Costo %6.%7",
		count _helis, _dn, mapGridPosition _pos, round (VIOC_ASS_HA_LIFE / 60), VIOC_ASS_HA_ZONE, _price, if (count _helis < VIOC_ASS_HA_N) then {format [" (solo salieron %1 de %2: %3; se te devolvieron %4)", count _helis, VIOC_ASS_HA_N, _err, _back]} else {""}],
		["heli", _helis select 0, _pos, VIOC_ASS_HA_ZONE]] call VIOC_AS_fnc_reply;
	[_side, format ["%1 pidio un ataque de helicopteros (%2) sobre la cuadricula %3.", _who, _dn, mapGridPosition _pos]] call VIOC_AS_fnc_sideSay;
	format ["Helicopteros de %1 (%2): %3 x %4 sobre %5, costo %6", _who, _side, count _helis, _cls, mapGridPosition _pos, _price] call VIOC_AS_fnc_log;
	[_e] spawn VIOC_HA_fnc_run;
	"ok"
};

//--- Vigila el ataque hasta que termina; luego espera del bando, aviso y regreso.
VIOC_HA_fnc_run = {
	params ["_e"];
	private _helis = _e get "helis";
	private _grps = _e get "grps";
	private _side = _e get "side";
	private _uid = _e get "uid";
	private _pname = _e get "pname";
	private _pos = _e get "center";
	private _id = _e get "id";
	private _t0 = time;
	private _attack = false;
	private _end = 1e10;
	private _why = "";
	private _gone = [];		//--- se fueron antes (danados o sin municion)
	private _down = [];		//--- derribados (ya avisados al recolector)
	private _next = 0;
	private _nextAmmo = time + 20;
	while {true} do {
		sleep 1;
		{
			if (!(_x in _down) && {!(_x in _gone)} && {[_x] call VIOC_HA_fnc_down}) then {	//--- los que se fueron antes los lleva planeGone
				_down pushBack _x;
				//--- revision: entero pero inmovil o sin piloto -> se borra (con su gente) cuando no hay jugadores cerca (o a los 15 min)
				if (!isNull _x && {alive _x}) then {[_x, _grps select _forEachIndex, [-1e5, -1e5, 0], 900] spawn VIOC_AS_fnc_planeGone} else {
					if (!isNull _x) then {_x setVariable ["VIOC_KEEP", false, true]};
					[_grps select _forEachIndex] spawn VIOC_AS_fnc_crewCleanup;
				};
			};
		} forEach _helis;
		private _act = _helis select {!(_x in _gone) && {!(_x in _down)}};
		if (count _act > 0) then {_e set ["plane", _act select 0]; _e set ["grp", _grps select (_helis find (_act select 0))]};
		if ((count _down) == (count _helis)) exitWith {_why = "lost"};
		if (count _act == 0) exitWith {_why = "gone"};
		if (missionNamespace getVariable ["CTI_GameOver", false]) exitWith {_why = "over"};
		if (_e getOrDefault ["end", false]) exitWith {_why = "forced"};
		if (_attack && {time >= _end}) exitWith {_why = "time"};
		if (!_attack && {(time - _t0) > VIOC_HA_ARRIVE_T}) exitWith {_why = "noarrive"};
		{if ((fuel _x) < 0.3) then {_x setFuel 1}} forEach _act;
		//--- llegada: todos a combate
		if (!_attack && {(_act findIf {(_x distance2D _pos) < VIOC_HA_NEAR}) >= 0}) then {
			_attack = true;
			_end = time + VIOC_ASS_HA_LIFE;
			_e set ["state", "attack"];
			{
				private _g = _grps select (_helis find _x);
				_g setBehaviour "COMBAT";
				_g setCombatMode "RED";
				_x flyInHeight VIOC_HA_FLY;
				[_g, _pos, _forEachIndex] call VIOC_HA_fnc_sad;
			} forEach _act;
			[_uid, format ["Helicopteros sobre la cuadricula %1: atacan durante %2 min.", mapGridPosition _pos, round (VIOC_ASS_HA_LIFE / 60)]] call VIOC_AS_fnc_note;
		};
		//--- danados o sin municion: se van antes
		private _chkAmmo = time > _nextAmmo;
		if (_chkAmmo) then {_nextAmmo = time + 10};
		{
			if (((damage _x) > 0.6) || {_attack && {_chkAmmo} && {!([_x] call VIOC_HA_fnc_hasAmmo)}}) then {
				_gone pushBack _x;
				[_x, _grps select (_helis find _x), _pos, _side] call VIOC_HA_fnc_home;
			};
		} forEach _act;
		//--- cada 5 s: blancos revelados, artillero al grupo de infanteria mas denso, correa y nueva orden SAD
		if (_attack && {time > _next}) then {
			_next = time + 5;
			([_pos, _side] call VIOC_HA_fnc_targets) params ["_men", "_veh"];
			private _best = objNull;
			private _bn = 0;
			{
				private _u = _x;
				private _n = {(_x distance _u) < 25} count _men;
				if (_n > _bn) then {_bn = _n; _best = _u};
			} forEach _men;
			{
				private _h = _x;
				if !(_h in _gone) then {
					private _k = _helis find _h;
					private _g = _grps select _k;
					{_g reveal [_x, 4]} forEach (_men + _veh);
					private _gun = gunner _h;
					if (_bn >= 3 && {!isNull _gun} && {alive _gun} && {!isPlayer _gun}) then {_gun doTarget _best; _gun doFire _best};
					if (((_h distance2D _pos) > (VIOC_HA_NEAR + 300)) && {time > (_h getVariable ["vioc_ha_leash", 0])}) then {
						_h setVariable ["vioc_ha_leash", time + 20];
						[_g, _pos, _k] call VIOC_HA_fnc_sad;
					} else {
						if ((currentWaypoint _g) >= (count (waypoints _g))) then {[_g, _pos, _k] call VIOC_HA_fnc_sad};
					};
				};
			} forEach (_act select {!(_x in _gone)});
		};
	};
	//--- fin
	private _kills = VIOC_HA_KILLS getOrDefault [_id, 0];
	VIOC_HA_KILLS deleteAt _id;
	private _nDown = count _down;
	private _lostTxt = if (_nDown > 0) then {format ["; %1 derribado%2", _nDown, ["s", ""] select (_nDown == 1)]} else {""};
	private _price = _e get "price";
	private _free = _e getOrDefault ["free", false];
	private _cd = VIOC_ASS_HA_CD;
	private _msg = "";
	switch (_why) do {
		case "lost": {
			_cd = VIOC_ASS_HA_CD_LOST;
			_msg = format ["Derribaron los %1 helicopteros (%2 enemigos abatidos). Los proximos estaran disponibles en %3.", count _helis, _kills, [_cd] call VIOC_AS_fnc_time];
		};
		case "time": {_msg = format ["Helicopteros: ataque terminado (%1 enemigos abatidos%2); regresan a base.", _kills, _lostTxt]};
		case "gone": {_msg = format ["Los helicopteros regresan a base antes de tiempo, danados o sin municion (%1 enemigos abatidos%2).", _kills, _lostTxt]};
		case "forced": {_msg = format ["Los helicopteros regresan a base (terminado desde la consola; %1 enemigos abatidos).", _kills]};
		case "noarrive": {
			_cd = 0;
			_msg = format ["Los helicopteros no llegaron al blanco: se cancela y se te devolvieron los %1.", _price];
			[_e, _price] call VIOC_AS_fnc_refund;
		};
		default {_cd = 0; _msg = "Los helicopteros regresan a base (la partida termino)."};
	};
	if (_free) then {_cd = 0};
	["heli", _side, _cd, ["done", "lost"] select (_why == "lost")] call VIOC_AS_fnc_setCD;
	[_uid, _msg, ["heli", _cd]] call VIOC_AS_fnc_note;
	if (_why == "lost") then {[_side, format ["Derribaron los helicopteros pedidos por %1; habra otros en %2.", _pname, [_cd] call VIOC_AS_fnc_time]] call VIOC_AS_fnc_sideSay};
	format ["Helicopteros de %1 (%2): fin '%3', %4 abatidos, %5 de %6 derribados", _pname, _side, _why, _kills, _nDown, count _helis] call VIOC_AS_fnc_log;
	VIOC_ASS_ACTIVE = VIOC_ASS_ACTIVE select {(_x get "id") != _id};
	{
		if (!(_x in _gone) && {!(_x in _down)}) then {[_x, _grps select (_helis find _x), _pos, _side] call VIOC_HA_fnc_home};
	} forEach _helis;
};

//--- Consola: los helicopteros de ese bando se van ya.
VIOC_HA_fnc_end = {
	params [["_side", west]];
	{if (((_x get "kind") == "heli") && {(_x get "side") == _side}) then {_x set ["end", true]}} forEach VIOC_ASS_ACTIVE;
	"orden de regreso enviada"
};

VIOC_ASS_GS_CD_LOST = (["VIOC_GUNSHIP_LOST_COOLDOWN", 30, 0, 180] call VIOC_AS_fnc_param) * 60;
//--- v3 heli_attack: helicopteros de ataque
VIOC_ASS_HA_ON = ["VIOC_HELI_ATTACK", 1, 0, 1] call VIOC_AS_fnc_param;
VIOC_ASS_HA_PRICE = ["VIOC_HELI_PRICE", 9000, 0, 1000000] call VIOC_AS_fnc_param;
VIOC_ASS_HA_CD = (["VIOC_HELI_COOLDOWN", 12, 0, 120] call VIOC_AS_fnc_param) * 60;
VIOC_ASS_HA_CD_LOST = (["VIOC_HELI_LOST_COOLDOWN", 30, 0, 180] call VIOC_AS_fnc_param) * 60;	//--- espera si los derriban a todos
VIOC_ASS_HA_LIFE = (["VIOC_HELI_DURATION", 5, 1, 30] call VIOC_AS_fnc_param) * 60;	//--- s sobre la zona desde que llega el primero
VIOC_ASS_HA_N = 3;			//--- helicopteros por ataque
VIOC_ASS_HA_ZONE = 300;		//--- m alrededor del blanco donde buscan enemigos
VIOC_ASS_HA_DANGER = 40;	//--- m: no se puede pedir con tropas propias a menos de esto del punto marcado

VIOC_AS_fnc_resetCD = {VIOC_ASS_CD = []; "esperas borradas"};

//--- v3: devuelve _amount del pedido _e a quien lo pago (nada si fue gratis). "aipay" = lo pago la IA (ai_air_support).
VIOC_AS_fnc_refund = {
	params ["_e", "_amount"];
	if (_amount <= 0 || {_e getOrDefault ["free", false]}) exitWith {};
	private _ai = _e getOrDefault ["aipay", []];
	if (count _ai > 0) exitWith {if (!isNil "VIOC_fnc_soCharge") then {[_e get "side", _ai, _amount] call VIOC_fnc_soCharge}};
	[_e get "pgrp", _e get "side", _amount] call CTI_CO_FNC_ChangeFunds;
};

case (_nat == "RU" && {_kind == 0}): {if (_rhs) then {["RHS_Su25SM_vvs", "CUP_O_Su25_Dyn_RU", "O_Plane_CAS_02_dynamicLoadout_F"]} else {["CUP_O_Su25_Dyn_RU", "RHS_Su25SM_vvs", "O_Plane_CAS_02_dynamicLoadout_F"]}};
//--- v3 heli_attack: _kind 2 = helicoptero de ataque (Colombia usa el de EE. UU.: _nat "US")
case (_nat == "US" && {_kind == 2}): {if (_rhs) then {["RHS_AH64D_wd", "RHS_AH64D", "CUP_B_AH64D_DL_USA", "B_Heli_Attack_01_dynamicLoadout_F"]} else {["CUP_B_AH64D_DL_USA", "RHS_AH64D_wd", "RHS_AH64D", "B_Heli_Attack_01_dynamicLoadout_F"]}};
case (_nat == "RU" && {_kind == 2}): {if (_rhs) then {["rhs_mi28n_vvs", "RHS_Ka52_vvs", "RHS_Mi24P_vvs", "CUP_O_Ka52_RU", "CUP_O_Mi24_P_Dynamic_RU", "O_Heli_Attack_02_dynamicLoadout_F"]} else {["CUP_O_Ka52_RU", "CUP_O_Mi24_P_Dynamic_RU", "rhs_mi28n_vvs", "RHS_Ka52_vvs", "O_Heli_Attack_02_dynamicLoadout_F"]}};
default {[]};

private _dn = if (_ki == 1) then {"Ghostrider"} else {getText (configFile >> "CfgVehicles" >> _cls >> "displayName")};
if (_ki == 2) then {_dn = "ataque de helicopteros"};
if (_ki == 0 && {(_mode < 0) || {_mode > 3} || {!(((VIOC_ASS_MODES select _si) select _mode) isEqualTo true)}}) exitWith {format ["el %1 no lleva armas para ese tipo de ataque", _dn]};

if (isNil "_ncrew" || {!(_ncrew isEqualType 0)}) then {_ncrew = 2};
if (_ki == 2) then {_ncrew = (_ncrew max 1) * VIOC_ASS_HA_N};
if (!_free && {!([_ncrew max 1] call VIOC_AS_fnc_perfOk)}) exitWith {"ahora hay demasiada IA en la partida (presupuesto VIOC_PERF_AI_MAX); prueba mas tarde"};

